import json
with open('/app/resources/treasury_bulletin_2011_12.json', 'r') as f:
    data = json.load(f)

# Look for keys that might contain Department of Labor
def find_labor(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'labor' in k.lower():
                print(f'Found: {path}.{k}')
            find_labor(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_labor(item, f'{path}[{i}]')

find_labor(data)
